]):?><optgroup label="Trilhas publicadas"><?php foreach($trails as$trail):$key='trail:'.(int)$trail['id'];?><option value="<?= $escape($key) ?>" data-price="<?= htmlspecialchars((string)(float)$trail['price'],ENT_QUOTES,'UTF-8') ?>" data-max-installments="<?= (int)$trail['max_installments'] ?>"<?= $key===$selectedProduct?' selected':'' ?>><?= $escape($trail['name'].' · Trilha com '.(int)$trail['item_count'].' Cursos individuais · R$ '.number_format((float)$trail['price'],2,',','.').' · até '.(int)$trail['max_installments'].'x') ?></option><?php endforeach;?></optgroup><?php endif;?></select><small data-enrollment-product-count>Ofertas sem AVA disponível ficam bloqueadas.</small></div>
